<template>
  <main class="login-page">
    <div class="ambient ambient-one"></div><div class="ambient ambient-two"></div>
    <section class="showcase">
      <BrandLogo />
      <div class="showcase-copy">
        <p class="eyebrow"><span></span> 高性能秒杀平台</p>
        <h1>让每一次心动，<br><em>快人一步。</em></h1>
        <p class="description">稳定承载高并发流量，带来流畅、安全、公平的限时抢购体验。</p>
        <div class="feature-list">
          <div class="feature-item"><span class="feature-icon"><svg viewBox="0 0 24 24" fill="none"><path d="m13.5 2-8 11h6l-1 9 8-12h-6l1-8Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg></span><div><strong>毫秒级响应</strong><small>高并发场景下依然流畅</small></div></div>
          <div class="feature-item"><span class="feature-icon"><svg viewBox="0 0 24 24" fill="none"><path d="M12 3 5 6v5c0 4.5 2.9 8.2 7 10 4.1-1.8 7-5.5 7-10V6l-7-3Z" stroke="currentColor" stroke-width="1.8"/><path d="m9 12 2 2 4-4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span><div><strong>安全有保障</strong><small>多重防护，守护每笔交易</small></div></div>
        </div>
      </div>
      <p class="copyright">© 2026 SeckillCore. 简单、快速、可靠。</p>
    </section>
    <section class="form-side">
      <div class="mobile-brand"><BrandLogo compact /></div>
      <div class="login-card">
        <div class="card-heading"><span class="welcome-icon">👋</span><h2>欢迎回来</h2><p>登录账号，开启你的秒杀之旅</p></div>
        <form novalidate @submit.prevent="handleSubmit">
          <div class="field" :class="{ invalid: errors.account }"><label for="account">账号</label><div class="input-wrap"><svg viewBox="0 0 24 24" fill="none"><path d="M20 21a8 8 0 0 0-16 0M12 13a5 5 0 1 0 0-10 5 5 0 0 0 0 10Z" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg><input id="account" v-model.trim="form.account" autocomplete="username" placeholder="请输入用户名或手机号" @input="errors.account = ''"></div><span v-if="errors.account" class="error-text">{{ errors.account }}</span></div>
          <div class="field" :class="{ invalid: errors.password }"><div class="label-row"><label for="password">密码</label><button class="text-button" type="button" @click="showNotice('请联系管理员重置密码')">忘记密码？</button></div><div class="input-wrap"><svg viewBox="0 0 24 24" fill="none"><rect x="4" y="10" width="16" height="11" rx="2" stroke="currentColor" stroke-width="1.7"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg><input id="password" v-model="form.password" :type="showPassword ? 'text' : 'password'" autocomplete="current-password" placeholder="请输入登录密码" @input="errors.password = ''"><button class="eye-button" type="button" :aria-label="showPassword ? '隐藏密码' : '显示密码'" @click="showPassword = !showPassword"><svg v-if="!showPassword" viewBox="0 0 24 24" fill="none"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z" stroke="currentColor" stroke-width="1.6"/><circle cx="12" cy="12" r="2.6" stroke="currentColor" stroke-width="1.6"/></svg><svg v-else viewBox="0 0 24 24" fill="none"><path d="m3 3 18 18M10.6 6.1A9.8 9.8 0 0 1 12 6c6 0 9.5 6 9.5 6a15 15 0 0 1-2 2.7M6.3 6.3C3.8 8 2.5 12 2.5 12s3.5 6 9.5 6c1.1 0 2.2-.2 3.1-.6M9.9 9.9a3 3 0 0 0 4.2 4.2" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg></button></div><span v-if="errors.password" class="error-text">{{ errors.password }}</span></div>
          <label class="remember"><input v-model="form.remember" type="checkbox"><span class="checkbox"></span>记住账号</label>
          <p v-if="submitError" class="submit-error" role="alert">{{ submitError }}</p>
          <button class="submit-button" type="submit" :disabled="loading"><span v-if="loading" class="spinner"></span>{{ loading ? '正在登录...' : '登 录' }}<svg v-if="!loading" viewBox="0 0 24 24" fill="none"><path d="m9 18 6-6-6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></button>
        </form>
        <div class="divider"><span>还没有账号？</span></div><button class="register-button" type="button" @click="router.push('/register')">创建新账号</button><p class="agreement">登录即表示你同意我们的 <a href="#">服务条款</a> 和 <a href="#">隐私政策</a></p>
      </div>
    </section>
    <Transition name="toast"><div v-if="notice" class="toast">{{ notice }}</div></Transition>
  </main>
</template>

<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import BrandLogo from '../components/BrandLogo.vue'
import { login } from '../api/auth'
import { getRememberedAccount, rememberAccount, saveSession } from '../utils/auth'

const router = useRouter(); const route = useRoute(); const rememberedAccount = getRememberedAccount()
const form = reactive({ account: rememberedAccount, password: '', remember: Boolean(rememberedAccount) }); const errors = reactive({ account: '', password: '' })
const showPassword = ref(false); const loading = ref(false); const submitError = ref(''); const notice = ref(''); let noticeTimer
onMounted(() => { if (route.query.registered === '1') showNotice('注册成功，请使用新账号登录') })
function validate() { errors.account = form.account ? '' : '请输入用户名或手机号'; errors.password = form.password ? '' : '请输入登录密码'; return !errors.account && !errors.password }
function showNotice(message) { notice.value = message; window.clearTimeout(noticeTimer); noticeTimer = window.setTimeout(() => { notice.value = '' }, 2400) }
async function handleSubmit() { submitError.value = ''; if (!validate() || loading.value) return; loading.value = true; try { const result = await login({ usernameOrPhone: form.account, password: form.password }); saveSession(result.data); rememberAccount(form.remember ? form.account : ''); await router.replace(typeof route.query.redirect === 'string' ? route.query.redirect : '/') } catch (error) { submitError.value = error.message } finally { loading.value = false } }
</script>

